-- V90.fh: Reliability Executive Governance & Escalation Control
-- Schema target: 234
CREATE TABLE IF NOT EXISTS maintenance_reliability_executive_governance_snapshot (snapshot_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, action_count INTEGER NOT NULL DEFAULT 0, open_action_count INTEGER NOT NULL DEFAULT 0, overdue_action_count INTEGER NOT NULL DEFAULT 0, high_priority_open_count INTEGER NOT NULL DEFAULT 0, evidence_gap_count INTEGER NOT NULL DEFAULT 0, effective_action_count INTEGER NOT NULL DEFAULT 0, ineffective_action_count INTEGER NOT NULL DEFAULT 0, governance_score NUMERIC NOT NULL DEFAULT 0, assessment TEXT NOT NULL DEFAULT 'NO_BASELINE', status TEXT NOT NULL DEFAULT 'OPEN', recommendation TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
CREATE TABLE IF NOT EXISTS maintenance_reliability_executive_governance_escalation (escalation_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, action_id TEXT NOT NULL, escalation_level TEXT NOT NULL, reason TEXT NOT NULL, owner_user_id TEXT, due_date DATE, status TEXT NOT NULL DEFAULT 'OPEN', resolution_note TEXT, evidence_note TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, resolved_by TEXT, resolved_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS maintenance_reliability_executive_governance_close (close_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, action_count INTEGER NOT NULL DEFAULT 0, open_escalation_count INTEGER NOT NULL DEFAULT 0, closed_by TEXT NOT NULL, closure_note TEXT, closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
CREATE INDEX IF NOT EXISTS ix_rel_exec_gov_scope ON maintenance_reliability_executive_governance_snapshot(organization_id,entity_id,period_key,status);
CREATE INDEX IF NOT EXISTS ix_rel_exec_gov_esc ON maintenance_reliability_executive_governance_escalation(organization_id,entity_id,period_key,status,escalation_level);
